class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    // Başlangıç zamanı ve mevcut jeton sayısı
    this._startTime = now();
    this._tokens = capacity;
  }

  _getCurrentTime() {
    return this.now();
  }

  _refill() {
    const currentTime = this._getCurrentTime();
    let elapsedSeconds = (currentTime - this._startTime) / 1000;

    // Sadece ileri zamanı hesaba kat, geri gitme yok
    if (elapsedSeconds < 0) {
      elapsedSeconds = 0;
    }

    const tokensToAdd = elapsedSeconds * this.refillPerSecond;
    this._tokens = Math.min(this.capacity, this._tokens + tokensToAdd);

    // Zamanı güncelle ki tekrar hesaplama yapmasın
    this._startTime = currentTime;
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n < 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this._tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n < 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    // İstenen jeton sayısı mevcut kapasiteden fazla veya dolum hızı sıfır
    if (n > this.capacity || this.refillPerSecond === 0) {
      return Infinity;
    }

    const needed = n - this._tokens;

    if (needed <= 0) {
      return 0;
    }

    // Saniyede kaç jeton dolar
    const secondsNeeded = needed / this.refillPerSecond;

    // Milisaniye olarak ve yukarı yuvarlanmış
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

