const { TokenBucket } = require('./kova.js');

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`✓ ${name}`);
    passed++;
  } catch (e) {
    console.log(`✗ ${name}: ${e.message}`);
    failed++;
  }
}

// Test 1: Başlangıçta dolu
test('Başlangıçta capacity kadar jeton', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  if (bucket.available() !== 10) throw new Error(`Beklenen 10, got ${bucket.available()}`);
});

// Test 2: tryTake başarılı
test('tryTake yeterli jeton varsa true döner', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  if (!bucket.tryTake(5)) throw new Error('Beklenen true');
});

// Test 3: tryTake başarısız
test('tryTake yeterli jeton yoksa false döner', () => {
  const bucket = new TokenBucket({ capacity: 3, refillPerSecond: 1 });
  if (bucket.tryTake(5)) throw new Error('Beklenen false');
});

// Test 4: tryTake sonrası jeton azalır
test('tryTake başarılı olursa jeton düşer', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  bucket.tryTake(5);
  if (bucket.available() !== 5) throw new Error(`Beklenen 5, got ${bucket.available()}`);
});

// Test 5: msUntil - yeterli jeton varsa 0
test('msUntil yeterli jeton varsa 0 döner', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  if (bucket.msUntil(8) !== 0) throw new Error(`Beklenen 0, got ${bucket.msUntil(8)}`);
});

// Test 6: msUntil - capacity'den fazla ise Infinity
test('msUntil capacity\'den fazla ise Infinity döner', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  if (bucket.msUntil(15) !== Infinity) throw new Error(`Beklenen Infinity`);
});

// Test 7: msUntil - refillPerSecond 0 ise ve yetmiyorsa Infinity
test('msUntil refillPerSecond=0 ve yetmiyorsa Infinity döner', () => {
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 0 });
  if (bucket.msUntil(10) !== Infinity) throw new Error(`Beklenen Infinity`);
});

// Test 8: msUntil - yukarı yuvarlama
test('msUntil doğru yuvarlar', () => {
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
  // 3 jeton eksik, 2 saniye gerekir -> 2000ms
  if (bucket.msUntil(8) !== 2000) throw new Error(`Beklenen 2000, got ${bucket.msUntil(8)}`);
});

// Test 9: Sahte saat ile dolum
test('Sahte saat ile dolum çalışır', () => {
  let time = 1000;
  const fakeNow = () => {
    time += 500;
    return time;
  };
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: fakeNow });

  // Başlangıçta 5 jeton
  if (bucket.available() !== 5) throw new Error('Başlangıç hatası');

  // 3 jeton al
  bucket.tryTake(3);

  // Zaman ilerledikçe dolum olmalı (1050ms -> 0.5s -> 1 jeton)
  fakeNow(); 
  const available = Math.round(bucket.available());
  if (available !== 4) throw new Error(`Beklenen ~4, got ${available}`);
});

// Test 10: Zaman geri gitme
test('Zaman geri gitmezse dolum hesaplanmaz', () => {
  let time = 1000;
  const fakeNow = () => {
    time -= 300; // Geri giden zaman
    return time;
  };
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: fakeNow });

  if (bucket.available() !== 5) throw new Error('İlk çağrıda hata');

  // Zaman geri gitti, dolum olmamalı
  if (bucket.available() !== 5) throw new Error('Zaman geri gitince dolum olmamalı');
});

// Test 11: RangeError - capacity negatif
test('RangeError: capacity negatif', () => {
  try { new TokenBucket({ capacity: -1 }); } catch(e) {}
  if (e instanceof RangeError) return;
  throw new Error('Beklenen RangeError');
}());

// Test 12: RangeError - capacity Infinity
test('RangeError: capacity Infinity', () => {
  try { new TokenBucket({ capacity: Infinity }); } catch(e) {}
  if (e instanceof RangeError) return;
  throw new Error('Beklenen RangeError');
}());

// Test 13: RangeError - refillPerSecond negatif
test('RangeError: refillPerSecond negatif', () => {
  try { new TokenBucket({ capacity: 5, refillPerSecond: -1 }); } catch(e) {}
  if (e instanceof RangeError) return;
  throw new Error('Beklenen RangeError');
}());

