test('msUntil n > capacity ise Infinity', () => {
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2 });
  if (bucket.msUntil(10) !== Infinity) throw new Error(`Beklenen Infinity`);
});

// Test 17: msUntil - n pozitif değilse RangeError
test('RangeError: msUntil n negatif', () => {
  const bucket = new TokenBucket({ capacity: 5, refillPerSecond: 2 });
  try { bucket.msUntil(-1); } catch(e) {}
  if (e instanceof RangeError) return;
  throw new Error('Beklenen RangeError');
}());

// Test 18: Capacity sıfır değil
test('RangeError: capacity sıfır', () => {
  try { new TokenBucket({ capacity: 0 }); } catch(e) {}
  if (e instanceof RangeError) return;
  throw new Error('Beklenen RangeError');
}());

